def order_by_points(nums):
    """
    Sorts the given list of integers in ascending order according to the sum of their digits.
    For negative numbers, the sum of digits is calculated by taking the absolute value,
    then making the most significant digit negative and the rest positive.
    If two numbers have the same digit sum, their original order is preserved.
    """
    def digit_sum(n):
        if n == 0:
            return 0
        abs_str = str(abs(n))
        digits = [int(ch) for ch in abs_str]
        if n > 0:
            return sum(digits)
        else:
            # negative: first digit negative, rest positive
            return -digits[0] + sum(digits[1:])

    # Python's sorted is stable, so equal keys retain original order
    return sorted(nums, key=digit_sum)
