        return txt.split()
    # If no whitespace, check for commas
    if ',' in txt:
        return txt.split(',')
    # Otherwise, count lowercase letters with odd alphabetical order (0-indexed)
    count = 0
    for c in txt:
        if 'a' <= c <= 'z':
            order = ord(c) - ord('a')
            if order % 2 == 1:
